def first_at_least(a, x):
    lo, hi = 0, len(a)          # the answer is always in lo..hi
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1        # a[mid] is too small, so is everything before it
        else:
            hi = mid            # a[mid] could be the answer, keep it
    return lo

