from collections import deque

def bfs_distances(graph, start):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if v not in dist:          # first time we see v: this is its shortest distance
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

