def merge(a, b):
    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

def sift_down(a, i, n):
    swaps = 0
    while True:
        left = 2 * i + 1
        right = left + 1
        if left >= n:
            return swaps
        if a[left] < a[i]:
            a[i], a[left] = a[left], a[i]
            i = left
            swaps += 1
        elif right < n and a[right] < a[i]:
            a[i], a[right] = a[right], a[i]
            i = right
            swaps += 1
        else:
            return swaps

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.count = n

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.size[rx] < self.size[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        self.size[rx] += self.size[ry]
        self.count -= 1
        return True

