class Node:
    def __init__(self, key):
        self.key, self.left, self.right, self.h = key, None, None, 0

def height(n):
    return -1 if n is None else n.h

def fix(n):
    n.h = 1 + max(height(n.left), height(n.right))

def rot_right(y):
    x = y.left
    y.left = x.right
    x.right = y
    fix(y); fix(x)
    return x

def rot_left(x):
    y = x.right
    x.right = y.left
    y.left = x
    fix(x); fix(y)
    return y

used = []

def insert(n, key):
    if n is None:
        return Node(key)
    if key < n.key:
        n.left = insert(n.left, key)
    else:
        n.right = insert(n.right, key)
    fix(n)
    bal = height(n.left) - height(n.right)
    if bal > 1:
        if height(n.left.left) >= height(n.left.right):
            used.append('R')
            return rot_right(n)
        n.left = rot_left(n.left)
        used.append('LR')
        return rot_right(n)
    if bal < -1:
        if height(n.right.right) >= height(n.right.left):
            used.append('L')
            return rot_left(n)
        n.right = rot_right(n.right)
        used.append('RL')
        return rot_left(n)
    return n

def preorder(n):
    return [] if n is None else [n.key] + preorder(n.left) + preorder(n.right)

